
/* =====================================
   1. CRIAÇÃO DA LISTA DE PRODUTOS
   ===================================== */

   let produtos = [];

   let proximoCodigo = 1;


   /* =====================================
      2. FUNÇÃO PARA VALIDAR PRODUTO
      ===================================== */

      function validarProduto(descricao, quantidade, valor) {

          if (descricao.trim() === "") {
                  return "A descrição é obrigatória!";
                      }

                          if (quantidade === "" || Number(quantidade) <= 0 ||
                                  !Number.isInteger(Number(quantidade))) {
                                          return "Informe uma quantidade inteira maior que zero!";
                                              }

                                                  if (valor === "" || !Number.isFinite(Number(valor)) ||
                                                          Number(valor) <= 0) {
                                                                  return "Informe um valor maior que zero!";
                                                                      }

                                                                          return null;
                                                                          }


                                                                          /* =====================================
                                                                             3. FUNÇÃO PARA CADASTRAR PRODUTO
                                                                             ===================================== */

                                                                             function cadastrarProduto(event) {

                                                                                 event.preventDefault();

                                                                                     const descricao = document.getElementById("descricao").value;
                                                                                         const quantidade = document.getElementById("quantidade").value;
                                                                                             const valor = document.getElementById("valor").value;

                                                                                                 const erro = validarProduto(descricao, quantidade, valor);

                                                                                                     if (erro) {
                                                                                                             mostrarMensagem(erro, "erro");
                                                                                                                     return;
                                                                                                                         }

                                                                                                                             // Criação do objeto produto

                                                                                                                                 const produto = {
                                                                                                                                         codigo: proximoCodigo++,
                                                                                                                                                 descricao: descricao.trim(),
                                                                                                                                                         quantidade: Number(quantidade),
                                                                                                                                                                 valor: Number(valor)
                                                                                                                                                                     };

                                                                                                                                                                         // Adicionando produto ao array

                                                                                                                                                                             produtos.push(produto);

                                                                                                                                                                                 mostrarMensagem("Produto cadastrado com sucesso!", "sucesso");

                                                                                                                                                                                     document.getElementById("formProduto").reset();

                                                                                                                                                                                         listarProdutos();
                                                                                                                                                                                         }


                                                                                                                                                                                         /* =====================================
                                                                                                                                                                                            4. FUNÇÃO PARA LISTAR PRODUTOS
                                                                                                                                                                                            ===================================== */

                                                                                                                                                                                            function listarProdutos() {

                                                                                                                                                                                                const lista = document.getElementById("listaProdutos");

                                                                                                                                                                                                    lista.innerHTML = "";

                                                                                                                                                                                                        produtos.forEach(function(produto) {

                                                                                                                                                                                                                const linha = document.createElement("tr");

                                                                                                                                                                                                                        const valores = [
                                                                                                                                                                                                                                    produto.codigo,
                                                                                                                                                                                                                                                produto.descricao,
                                                                                                                                                                                                                                                            produto.quantidade,
                                                                                                                                                                                                                                                                        produto.valor.toLocaleString("pt-BR", {
                                                                                                                                                                                                                                                                                        style: "currency",
                                                                                                                                                                                                                                                                                                        currency: "BRL"
                                                                                                                                                                                                                                                                                                                    })
                                                                                                                                                                                                                                                                                                                            ];

                                                                                                                                                                                                                                                                                                                                    valores.forEach(function(valor) {
                                                                                                                                                                                                                                                                                                                                                const coluna = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                            coluna.textContent = valor;
                                                                                                                                                                                                                                                                                                                                                                        linha.appendChild(coluna);
                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                        lista.appendChild(linha);

                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                            /* =====================================
                                                                                                                                                                                                                                                                                                                                                                                               5. FUNÇÃO PARA ATUALIZAR O VALOR
                                                                                                                                                                                                                                                                                                                                                                                               ===================================== */

                                                                                                                                                                                                                                                                                                                                                                                               function atualizarValor() {

                                                                                                                                                                                                                                                                                                                                                                                                   const codigo = Number(
                                                                                                                                                                                                                                                                                                                                                                                                           document.getElementById("codigoValor").value
                                                                                                                                                                                                                                                                                                                                                                                                               );

                                                                                                                                                                                                                                                                                                                                                                                                                   const novoValor = document.getElementById("novoValor").value;

                                                                                                                                                                                                                                                                                                                                                                                                                       if (!Number.isInteger(codigo) || codigo <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                               mostrarMensagem("Informe um código válido!", "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                       return;
                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                               if (novoValor === "" ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                       !Number.isFinite(Number(novoValor)) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                               Number(novoValor) <= 0) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                       mostrarMensagem("Informe um valor válido!", "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                               return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // Busca do produto utilizando find

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const produto = produtos.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // Tratamento de produto não encontrado

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       mostrarMensagem("Produto não encontrado!", "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       produto.valor = Number(novoValor);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           mostrarMensagem("Valor atualizado com sucesso!", "sucesso");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   document.getElementById("codigoValor").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       document.getElementById("novoValor").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       /* =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          6. FUNÇÃO PARA ATUALIZAR QUANTIDADE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ===================================== */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function atualizarQuantidade() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const codigo = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.getElementById("codigoQuantidade").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const quantidade = document.getElementById("novaQuantidade").value;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!Number.isInteger(codigo) || codigo <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          mostrarMensagem("Informe um código válido!", "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (quantidade === "" ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  !Number.isInteger(Number(quantidade)) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Number(quantidade) <= 0) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  mostrarMensagem("Informe uma quantidade válida!", "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Procurando o produto pelo código

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const produto = produtos.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              mostrarMensagem("Produto não encontrado!", "erro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Somando a quantidade ao estoque atual

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  produto.quantidade += Number(quantidade);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      mostrarMensagem("Estoque atualizado com sucesso!", "sucesso");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              document.getElementById("codigoQuantidade").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.getElementById("novaQuantidade").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  /* =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     7. FUNÇÃO PARA MOSTRAR MENSAGENS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ===================================== */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     function mostrarMensagem(texto, tipo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const mensagem = document.getElementById("mensagem");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             mensagem.textContent = texto;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 mensagem.className = tipo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 /* =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    8. INICIALIZAÇÃO DO SISTEMA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ===================================== */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("formProduto")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .addEventListener("submit", cadastrarProduto);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        